function validate([points]) {
  if (!Array.isArray(points) || points.length < 1 || points.length > 100000) return 'points needs 1 to 100000 balloons.';
  for (const p of points) {
    if (!Array.isArray(p) || p.length !== 2 || !p.every(Number.isInteger)) return 'Each balloon is a pair of integers [xstart, xend].';
    if (p[0] < -2147483648 || p[1] > 2147483647) return 'Coordinates fit in a 32-bit signed integer.';
    if (p[0] >= p[1]) return 'Each balloon needs xstart < xend.';
  }
  return null;
}

