function findMinArrowShots(points) {
  points.sort((a, b) => a[1] - b[1]);
  let arrows = 1;
  let arrowX = points[0][1];

  for (let i = 1; i < points.length; i++) {
    const [start, end] = points[i];
    if (start > arrowX) {
      arrows++;
      arrowX = end;
    }
  }
  return arrows;
}

