function findMinArrowShots(points) {
  // Some optimal set of arrows uses only balloon right ends, so try every subset of them.
  const spots = [...new Set(points.map(p => p[1]))];
  let best = points.length;
  for (let mask = 1; mask < 1 << spots.length; mask++) {
    const chosen = spots.filter((_, k) => mask & (1 << k));
    if (chosen.length >= best) continue;
    if (points.every(([s, e]) => chosen.some(x => s <= x && x <= e))) best = chosen.length;
  }
  return best;
}

