function generate(rand, size) {
  const MIN = -2147483648, MAX = 2147483647;
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 8);
    const span = rand() < 0.5 ? 6 : 15;
    const edge = rand() < 0.1;
    const points = [];
    for (let k = 0; k < n; k++) {
      if (edge && rand() < 0.5) {
        points.push(rand() < 0.5 ? [MIN, MIN + int(1, 3)] : [MAX - int(1, 3), MAX]);
        continue;
      }
      const start = int(-span, span - 1);
      points.push([start, int(start + 1, Math.min(span, start + 1 + int(0, span)))]);
    }
    return [points];
  }
  const n = 2000;
  const mode = rand();
  const range = mode < 0.3 ? 1e9 : mode < 0.6 ? 1e6 : 1e4;
  const maxLength = Math.max(1, Math.floor(range / (mode < 0.8 ? 400 : 20)));
  const points = [];
  for (let k = 0; k < n; k++) {
    const start = Math.max(MIN, Math.min(MAX - 1, int(-range, range)));
    points.push([start, Math.min(MAX, start + int(1, maxLength))]);
  }
  if (mode > 0.9) points[0] = [MIN, MIN + 1], points[1] = [MAX - 1, MAX];
  return [points];
}
